import { NextResponse } from "next/server";
import { apiError, readJsonBody, serverError } from "@/lib/api";
import { insertOrder, readOrder } from "@/lib/supabase/store";
import { parseOrderInput } from "@/lib/transactions";

/** Creates the order a customer just checked out. Public on purpose. */
export async function POST(request: Request) {
  try {
    const order = parseOrderInput(await readJsonBody(request));
    if (!order) return apiError("Data pesanan tidak lengkap atau tidak valid.");

    // The ID is generated by the client, so guard against the rare collision
    // instead of silently overwriting someone else's order.
    if (await readOrder(order.id)) {
      return apiError(`ID transaksi ${order.id} sudah terpakai. Silakan ulangi transaksi.`, 409);
    }

    const created = await insertOrder(order);
    return NextResponse.json({ order: created }, { status: 201 });
  } catch (error) {
    return serverError(error);
  }
}
